1	// Shared game-server order core — the ONE audited debit path for game servers,
2	// used by the wallet flow (lib/actions-gameplans.ts payAndDeployGame /
3	// orderGameServer) AND the Stripe confirm/webhook fulfilment (lib/fulfil-checkout.ts)
4	// so a card-paid game order provisions through the SAME machinery a VPS order does.
5	// Plain server module (NOT "use server") — no secrets, callable from actions,
6	// server components and the worker/webhook alike.
7	//
8	// This is the game analogue of lib/order.ts (orderQuote / placeOrder). It was
9	// factored OUT of the original `orderGameServer` so the card path and the wallet
10	// path settle through one function instead of two copies that could drift.
11	//
12	// MONEY RULES (audited):
13	//   - Prices are strictly DB-fed: `gamePlan.priceCents` is the ONLY source, priced
14	//     through the SAME `termPriceCents` formula the deploy wizard shows and the
15	//     renewal sweep bills (displayed === charged === renewed).
16	//   - Game bills FULL from month 1. There is NO first-month-free on game (that promo
17	//     is Shared-Web-Hosting-only); no $0 path, no coupon, no VAT change here.
18	//   - The wallet is the single debit; `debitWallet` refuses to overdraw.
19	//   - `sold` (card path) carries the price the order was SOLD at, stamped BEFORE the
20	//     card cleared, so fulfilment never re-prices after the money moved (the H2
21	//     incident guarded on lib/order.ts OrderPrice).
22	import { Prisma } from "@prisma/client";
23	import type { User } from "@prisma/client";
24	import { db } from "./db";
25	import { debitWallet, InsufficientBalanceError } from "./wallet";
26	import { addMonths, normalizeProductTerm, termPriceCents, vpsTerm } from "./billing-terms";
27	import { annualDiscountPct } from "./annual-discount";
28	import { capacityCheck } from "./capacity";
29	import { GAME_FAMILIES, type GameFamily } from "./games";
30	import { schemaFor, isValidVariant, validateConfig } from "./game-config";
31	
32	export class GameOrderError extends Error {}
33	
34	/** Hostname rules mirror the VPS order path (lib/order.ts orderSchema). */
35	const HOSTNAME_RE = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i;
36	
37	/** Short random suffix so auto-generated hostnames don't collide. */
38	export function randSuffix(n = 6): string {
39	  return Math.random().toString(36).slice(2, 2 + n);
40	}
41	
42	/**
43	 * The customer's full game-order intent — the tier, the billing term and the
44	 * per-game setup captured by the wizard. `config` holds the raw gameplay values
45	 * (validated against the family schema in `gameOrderQuote`); `variant` is the
46	 * server type/loader.
47	 */
48	export type GameOrderIntent = {
49	  gamePlanId: string;
50	  /** 1 (Monthly) or 12 (Annual) — normalised through normalizeProductTerm. */
51	  termMonths: number;
52	  /** Optional customer-facing nickname → Server.label. */
53	  serverName?: string;
54	  /** DNS-safe hostname → Server.name/hostname. Blank => auto-generated. */
55	  hostname?: string;
56	  /** Game type/loader id (e.g. "paper", "carbon"); validated per family. */
57	  variant?: string;
58	  /** Raw gameplay settings; validated + coerced against the family schema. */
59	  config?: Record<string, unknown> | null;
60	};
61	
62	/**
63	 * The price a game order was SOLD at, stamped onto the Stripe session BEFORE the
64	 * card was charged and read back at fulfilment. Game has no promo/coupon/tax, so
65	 * this is just the net charge — a deliberately tiny shape (compare lib/order.ts
66	 * OrderPrice, which must also carry promo + VAT).
67	 */
68	export type GameOrderPrice = { chargeCents: number };
69	
70	/** Parse a sold game price back off Stripe metadata; null unless well-formed. */
71	export function parseGameOrderPrice(raw: unknown): GameOrderPrice | null {
72	  let obj: unknown = raw;
73	  if (typeof raw === "string") {
74	    try {
75	      obj = JSON.parse(raw);
76	    } catch {
77	      return null;
78	    }
79	  }
80	  if (!obj || typeof obj !== "object") return null;
81	  const { chargeCents } = obj as Record<string, unknown>;
82	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
83	  return { chargeCents };
84	}
85	
86	export type GameOrderQuote = {
87	  gamePlanId: string;
88	  gameFamily: string;
89	  planName: string;
90	  basePlanId: string;
91	  osTemplateId: string;
92	  /** Normalised term (1 or 12). */
93	  term: number;
94	  /** Annual-discount rate resolved at quote time; frozen onto the Server at sale. */
95	  annualPct: number;
96	  /** DB-fed per-month base (priceCents / termMonths). */
97	  monthlyCents: number;
98	  /** The net charge for the whole term — displayed === charged === renewed. */
99	  chargeCents: number;
100	  hostname: string;
101	  label: string | null;
102	  variant: string;
103	  /** Clean, fully-populated gameplay values ready to persist (may be empty). */
104	  values: Record<string, string | number | boolean>;
105	};
106	
107	/**
108	 * Validate + price a game order without placing it. Throws GameOrderError on any
109	 * problem. Pure of side effects beyond reads. The price is the whole truth about
110	 * what this order costs; the caller (wallet split, review step, checkout stamp)
111	 * quotes from THIS so what the customer sees is what settles.
112	 */
113	export async function gameOrderQuote(intent: GameOrderIntent): Promise<GameOrderQuote> {
114	  const term = normalizeProductTerm(intent.termMonths);
115	
116	  const gp = await db.gamePlan.findUnique({
117	    where: { id: intent.gamePlanId },
118	    include: { basePlan: true },
119	  });
120	  if (!gp || !gp.active) throw new GameOrderError("That game plan isn't available.");
121	  if (!gp.basePlan?.active) throw new GameOrderError("Provisioning is temporarily unavailable for this game.");
122	  if (!GAME_FAMILIES.includes(gp.gameFamily as GameFamily)) {
123	    throw new GameOrderError("Unknown game family.");
124	  }
125	
126	  // Resolve the game image: the tier's own OsTemplate, else any active image for
127	  // this family. A game server can't provision without an image.
128	  let osTemplateId = gp.osTemplateId;
129	  if (osTemplateId) {
130	    const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
131	    if (!os?.active) osTemplateId = null;
132	  }
133	  if (!osTemplateId) {
134	    const os = await db.osTemplate.findFirst({
135	      where: { family: gp.gameFamily, category: "APPLICATION", active: true },
136	      orderBy: { sortOrder: "asc" },
137	    });
138	    if (!os) throw new GameOrderError("No game image is configured for this game yet.");
139	    osTemplateId = os.id;
140	  }
141	
142	  // Hostname: validate a provided one strictly, else auto-generate a safe one.
143	  const rawHost = (intent.hostname ?? "").trim().toLowerCase();
144	  let hostname = rawHost;
145	  if (hostname === "") {
146	    hostname = `${gp.gameFamily}-${randSuffix()}`;
147	  } else if (!(hostname.length >= 3 && hostname.length <= 40 && HOSTNAME_RE.test(hostname))) {
148	    throw new GameOrderError(
149	      "Hostname must be 3–40 characters, using only letters, digits and hyphens, and cannot start or end with a hyphen.",
150	    );
151	  }
152	
153	  const label = (intent.serverName ?? "").trim().slice(0, 60) || null;
154	
155	  // Per-game setup: variant + gameplay settings, validated against the family
156	  // schema. Families without a customization schema (e.g. Terraria) carry no
157	  // variant and no gameplay values — the wizard shows only identity fields for them.
158	  const schema = schemaFor(gp.gameFamily);
159	  let variant = "";
160	  let values: Record<string, string | number | boolean> = {};
161	  if (schema) {
162	    variant = (intent.variant ?? "").trim() || schema.defaultVariant;
163	    if (!isValidVariant(gp.gameFamily, variant)) {
164	      throw new GameOrderError("Choose a valid server type for this game.");
165	    }
166	    const res = validateConfig(gp.gameFamily, intent.config ?? {});
167	    if (!res.ok) throw new GameOrderError(res.error);
168	    values = res.values;
169	  }
170	
171	  // Price: DB-fed base × term, annual discount resolved ONCE and frozen at sale.
172	  // Every seeded plan is `termMonths: 1`, so monthlyCents === priceCents; the
173	  // divisor keeps the maths correct if a multi-month base plan is ever configured.
174	  const annualPct = await annualDiscountPct();
175	  const monthlyCents = Math.round(gp.priceCents / Math.max(1, gp.termMonths));
176	  const chargeCents = termPriceCents(monthlyCents, term, annualPct);
177	
178	  return {
179	    gamePlanId: gp.id,
180	    gameFamily: gp.gameFamily,
181	    planName: gp.name,
182	    basePlanId: gp.basePlanId,
183	    osTemplateId,
184	    term,
185	    annualPct,
186	    monthlyCents,
187	    chargeCents,
188	    hostname,
189	    label,
190	    variant,
191	    values,
192	  };
193	}
194	
195	/**
196	 * Place a game order: re-validate + price, capacity-check, then atomically debit
197	 * the wallet and create the Server (sized by the tier's base VPS plan, running the
198	 * game image, with the customer's variant + gameplay settings) plus a PROVISION
199	 * job. Returns the new server id. Does NOT redirect.
200	 *
201	 * `sold` (card path) overrides the recomputed price with the one the order was
202	 * SOLD at — the card-paid path passes the figure stamped on the Checkout session
203	 * BEFORE the card was charged, so the confirm/webhook fulfilment settles the price
204	 * the customer consented to instead of re-pricing against a rate that changed in
205	 * between. The wallet path omits it and pays the fresh quote it computed moments
206	 * ago. This mirrors `sold` in lib/order.ts placeOrder.
207	 *
208	 * Callers must ensure funds exist (the card leg pre-credits the wallet, the wallet
209	 * path is gated by the balance check in the action). This still enforces the
210	 * balance and throws GameOrderError("Insufficient balance…") otherwise — no overdraft.
211	 */
212	export async function placeGameOrder(
213	  user: User,
214	  intent: GameOrderIntent,
215	  sold?: GameOrderPrice | null,
216	): Promise<string> {
217	  const quote = await gameOrderQuote(intent);
218	
219	  // Bill off the SOLD price when present (never re-priced after the card cleared),
220	  // else the fresh quote. Game has no promo/coupon, so this scalar is the whole
221	  // truth about what this order costs.
222	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
223	
224	  // Oversell guard — the VPS order path enforces this; game orders must too, or a
225	  // game server could commit host RAM past capacity.
226	  const capacity = await capacityCheck(quote.basePlanId);
227	  if (!capacity.ok) {
228	    throw new GameOrderError(capacity.reason ?? "The host is at capacity right now. Please try again shortly.");
229	  }
230	
231	  // Balance gate BEFORE the tx so we fail cleanly (no money moved). On the card
232	  // path the wallet was credited the card leg first, so this holds.
233	  if (user.balanceCents < chargeCents) {
234	    throw new GameOrderError("Insufficient balance. Top up your wallet first.");
235	  }
236	
237	  const effMonthly = quote.term > 1 ? Math.round(chargeCents / quote.term) : 0;
238	  const termLabel =
239	    quote.term > 1 ? `${vpsTerm(quote.term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(quote.term).label;
240	
241	  let server;
242	  try {
243	    server = await db.$transaction(async (tx) => {
244	      await debitWallet(tx, user.id, chargeCents);
245	      await tx.walletTransaction.create({
246	        data: {
247	          userId: user.id,
248	          amountCents: -chargeCents,
249	          description: `Game server: ${quote.planName} (${quote.gameFamily}) — ${termLabel}`,
250	        },
251	      });
252	      const s = await tx.server.create({
253	        // Cast: the symlinked prod Prisma client's types predate `annualDiscountPct`
254	        // on Server until regenerated at deploy (see lib/order.ts's Server create).
255	        data: {
256	          name: quote.hostname,
257	          hostname: quote.hostname,
258	          label: quote.label,
259	          userId: user.id,
260	          planId: quote.basePlanId,
261	          gamePlanId: quote.gamePlanId,
262	          osTemplateId: quote.osTemplateId,
263	          // The customer's per-game setup, applied at the point of sale — the worker
264	          // renders these into the game's own config at provision (worker/game-config).
265	          gameVariant: quote.variant || null,
266	          gameConfig: Object.keys(quote.values).length > 0 ? quote.values : Prisma.JsonNull,
267	          // The chosen term rides the Server row (Monthly / Annual); renewalCharge's
268	          // game branch renews monthlyCents × termMonths × (1 − annual).
269	          termMonths: quote.term,
270	          // No seasonal promo on game — this term was sold at 0% off, so any future
271	          // proration prices against full price.
272	          termPromoPercent: 0,
273	          // The annual rate frozen at sale, so the renewal bills the SAME price the
274	          // order charged even if the admin retunes annual_discount_percent later.
275	          annualDiscountPct: quote.annualPct,
276	          wantsDedicatedIp: false,
277	          expiresAt: addMonths(new Date(), quote.term),
278	        } as Prisma.ServerUncheckedCreateInput,
279	      });
280	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
281	      return s;
282	    });
283	  } catch (e) {
284	    if (e instanceof InsufficientBalanceError) {
285	      throw new GameOrderError("Insufficient balance. Top up your wallet first.");
286	    }
287	    throw e;
288	  }
289	
290	  await db.auditLog.create({
291	    data: {
292	      userId: user.id,
293	      action: "gameserver.order",
294	      detail: `${server.id} game=${quote.gameFamily} tier=${quote.planName} term=${quote.term}mo${sold ? " card" : " wallet"}`,
295	    },
296	  });
297	  return server.id;
298	}
