130	   * this net. The amount actually CHARGED is `chargeCents + (taxCents ?? 0)`.
131	   */
132	  chargeCents: number;
133	  /** Promo rate (%) that produced it; persisted as `Server.termPromoPercent`. */
134	  promoPercent: number;
135	  /** Promo name for the ledger / invoice line, e.g. "Summer Sale". */
136	  promoName: string;
137	  /**
138	   * VAT/GST on the net (Finding 1), carried through the card round-trip so the
139	   * confirm route settles the SAME tax-inclusive total the card leg was split from
140	   * — never re-derived after the card cleared. Absent on legacy/full-price sessions,
141	   * in which case the charge path recomputes it from the owner's country (0 by
142	   * default), which can only ever undertax, the conservative direction.
143	   */
144	  taxCents?: number;
145	  taxRatePercent?: number;
146	  taxCountry?: string;
