156	    promo: { discountPercent: number; name: string };
157	  },
158	  tax?: { taxCents: number; ratePercent: number; country: string } | null,
159	): OrderPrice {
160	  return {
161	    chargeCents: quote.chargeCents,
162	    promoPercent: quote.promo.discountPercent,
163	    promoName: quote.promo.name,
164	    ...(tax
165	      ? { taxCents: tax.taxCents, taxRatePercent: tax.ratePercent, taxCountry: tax.country }
