191	  // malformed tax field) carries none, and the charge path recomputes tax from the
192	  // owner's country — which undertaxes at worst, never overcharges.
193	  const tc = typeof taxCents === "number" && Number.isInteger(taxCents) && taxCents >= 0 ? taxCents : 0;
194	  const tr =
195	    typeof taxRatePercent === "number" && Number.isFinite(taxRatePercent) && taxRatePercent >= 0
196	      ? taxRatePercent
197	      : 0;
198	  return {
199	    chargeCents,
200	    promoPercent,
201	    promoName: typeof promoName === "string" ? promoName : "",
202	    taxCents: tc,
203	    taxRatePercent: tr,
204	    taxCountry: typeof taxCountry === "string" ? taxCountry : "",
205	  };
206	}
