237	/**
238	 * Pick the least-committed enabled node (RAM headroom), while steering AWAY from
239	 * a node this order would push to/past the CRITICAL capacity threshold when
240	 * another node has room. Falls back to primary (any node) when every candidate is
241	 * already critical — the scheduler never REFUSES an order for a capacity warning
242	 * (that's the node-capacity alert's job, lib/node-capacity.ts); it only prefers a
243	 * roomier node when one exists. DB-only so order placement never blocks on a
244	 * Proxmox round trip.
245	 */
246	async function scheduleNode(planRamMB: number) {
247	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
248	  if (nodes.length === 0) return null;
249	  const loads = await Promise.all(
250	    nodes.map(async (n) => {
251	      const agg = await db.server.findMany({
252	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
253	        select: { plan: { select: { ramMB: true } } },
254	      });
255	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
256	      // Commitment AFTER this VM lands — that's what decides whether placing here
257	      // tips the node critical.
258	      const projectedPct = n.capacityRamMB > 0 ? ((used + planRamMB) / n.capacityRamMB) * 100 : 100;
259	      return { node: n, free: n.capacityRamMB - used, projectedPct };
260	    }),
261	  );
262	  const { critPct } = await nodeThresholds();
263	  const roomy = loads.filter((l) => l.projectedPct < critPct);
264	  const pool = roomy.length > 0 ? roomy : loads;
265	  pool.sort((a, b) => b.free - a.free);
266	  return pool[0].node;
267	}
