269	/** Validate + price an order without placing it. Throws OrderError on any problem. */
270	export async function orderQuote(intent: OrderIntent, opts?: { suppressPromo?: boolean }) {
271	  const parsed = orderSchema.safeParse(intent);
272	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
273	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
274	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
275	  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
276	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
277	    throw new OrderError(
278	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
279	    );
280	  }
281	  const term = vpsTerm(Number(intent.termMonths ?? 1));
282	  // The admin-configured ANNUAL discount, resolved ONCE here and passed to
283	  // `vpsTermPriceCents` so the annual term is charged at the same rate the deploy
284	  // wizard displayed and every renewal will bill. Ignored for non-annual terms.
285	  const annualPct = await annualDiscountPct();
286	  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
287	
288	  // Extra root disk, priced per GB/month and multiplied over the term exactly
289	  // like the dedicated-IP add-on (and, like it, NOT discounted by the term or the
290	  // promo — the customer pays the same $/GB whichever term they pick, and renews
291	  // at the same rate). Growth is one-way: this is permanent for the server.
292	  const extraDiskGB = normalizeExtraDiskGB(intent.extraDiskGB);
293	  const extraDiskPerGb = extraDiskGB > 0 ? await extraDiskPerGbCents() : 0;
294	  const extraDiskMonthlyCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGb);
295	  const extraDiskCents = extraDiskMonthlyCents * term.months;
296	  if (effectiveDiskGB(plan.diskGB, extraDiskGB) > EXTRA_DISK_MAX_TOTAL_GB) {
297	    throw new OrderError(`A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB.`);
298	  }
299	
300	  // Paid backup RETENTION tier, priced per month and multiplied over the term
301	  // exactly like the extra-disk add-on (NOT promo-discounted — the customer pays
302	  // the same $/mo whichever term or promo, and renews at the same rate through
303	  // renewalCharge). Only PLUS is paid; FREE (the included tier) is $0.
304	  const backupTier = normalizeBackupTier(intent.backupTier);
305	  const backupMonthlyCents =
306	    backupTier === "FREE" ? 0 : backupTierMonthlyCents(backupTier, await backupPlusMonthlyCents());
307	  const backupCents = backupMonthlyCents * term.months;
308	
309	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
310	  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
311	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
312	  // real renewal price and this discounted value is the real first-term price.
313	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
314	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
315	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months, annualPct);
316	
317	  // LOW intro price → RENEWS at regular. A per-plan `introPriceCents` (set by an
318	  // admin) makes the FIRST term cheaper and leaves every renewal at the regular
319	  // `priceCents` — renewal code never reads the intro column, so renewal === regular
320	  // by construction (lib/renewal-charge.ts). Modelled as a first-term REDUCTION of
321	  // the regular term total (not a second price), so the regular term stays the one
322	  // basis renewals bill and proration prices against. `introDiscountCents` is 0 for
323	  // every plan without an intro price, so the whole VPS flow below is unchanged for
324	  // them. VPS never carries the first-month-free promo (`firstMonthFreeAppliesTo`),
325	  // so intro and FMF never stack here.
326	  const introMonthlyCents = planIntroMonthlyCents(plan);
327	  const introTermMonths = planIntroTermMonths(plan);
328	  const introDiscountCents = introFirstTermDiscountCents(
329	    plan.priceCents,
330	    introMonthlyCents,
331	    term.months,
332	    introTermMonths,
333	    annualPct,
334	  );
335	  // The plan-portion cash the FIRST term is sold at, intro applied. Renewals ignore it.
336	  const introFirstTermPlanCents = Math.max(0, regularPlanCents - introDiscountCents);
337	  // The rate this first term is sold at (percent off the regular term total) — stamped
338	  // on Server.termPromoPercent below via the promo object so proration/refunds price
339	  // against it exactly like a seasonal promo.
340	  const introPercent = introSoldPercent(regularPlanCents, introDiscountCents);
341	  const introRenewalMonthly = plan.priceCents; // what the "then $X/mo" copy quotes
342	  // When a plan has an intro price we present it THROUGH the same `promo` channel the
343	  // seasonal-sale plumbing uses (name + percent travel on OrderPrice and stamp
344	  // termPromoPercent). `firstMonthFree: false` keeps it out of the one-month-free
345	  // redemption machinery — an intro price has no per-account cap; it is simply this
346	  // plan's first-term price.
347	  const promo =
348	    introDiscountCents > 0
349	      ? {
350	          id: "intro-price",
351	          name: `Intro price — renews at $${(introRenewalMonthly / 100).toFixed(2)}/mo`,
352	          label: "Intro price",
353	          discountPercent: introPercent,
354	          firstMonthFree: false,
355	        }
356	      : currentPromo(new Date());
357	  // The promo is now MANAGED: the owner can switch it off, and every claim is
358	  // capped 1/account + 1/IP (lib/promo-redemption.ts). When the toggle is off the
359	  // quote shows — and placeOrder charges — the full price, so display === charged
360	  // on the disabled path. When it is on, the quote shows the first-month-free
361	  // price and the atomic claim in placeOrder's tx is the final arbiter of whether
362	  // the credit is actually granted (a lost race there is charged full).
363	  // `suppressPromo` prices this quote at FULL price even when the promo is on —
364	  // the card path uses it to re-quote for a customer who has already redeemed
365	  // (per-account/IP), so their Stripe leg and stamped total are full, not free.
366	  // The first-month-free promo is scoped to Shared Web Hosting only — VPS always
367	  // bills full. `firstMonthFreeAppliesTo("VPS")` is false, so promoEnabled is
368	  // false here and planFirstTermCents falls through to the regular term total.
369	  const promoEnabled =
370	    firstMonthFreeAppliesTo("VPS") && !opts?.suppressPromo && (await firstMonthFreeEnabled());
371	  // First-month-free must credit exactly ONE MONTH — not zero a multi-month term.
372	  // A naive promoPriceCents(termTotal) at 100% off would give a 36-month term 3
373	  // YEARS free. So we subtract one month of the plan's rate from the term total.
374	  // For a 1-month term this lands at $0 (genuinely first month free); for a 12/24/
375	  // 36-month term the customer pays the term minus one month. Renewals bill the
376	  // full vpsTermPriceCents unchanged (worker/billing.ts) — displayed === charged.
377	  const planFirstTermCents =
378	    promoEnabled && promo.firstMonthFree
379	      ? Math.max(0, regularPlanCents - plan.priceCents)
380	      : regularPlanCents;
381	  // The one-month credit this order gets IF the atomic claim succeeds. 0 when the
382	  // promo is off. placeOrder adds it back to charge full when the claim is lost.
383	  const promoCreditCents = regularPlanCents - planFirstTermCents;
384	
385	  // Optional checkout coupon: a service-locked, term-capped discount on the PLAN
386	  // portion only (not the dedicated-IP or extra-disk add-ons). Never throws for a
387	  // bad code — an invalid coupon leaves the price at full and surfaces `couponError`
388	  // so the deploy preview can show it; the redemption itself (count + per-user +
389	  // per-IP guards) is claimed atomically in placeOrder.
390	  let couponId: string | null = null;
391	  let couponDiscountCents = 0;
392	  let couponLabel = "";
393	  let couponError = "";
394	  let couponMaxRedemptions: number | null = null;
395	  let couponFirstTimeOnly = false;
396	  const code = (intent.couponCode ?? "").trim().toUpperCase();
397	  if (code) {
398	    if (!(await getSettingBool("coupons_enabled", true))) {
399	      couponError = "Promo codes are currently disabled.";
400	    } else {
401	      const coupon = await db.coupon.findUnique({ where: { code } });
402	      if (!coupon) {
403	        couponError = "That code isn’t valid.";
404	      } else {
405	        const verdict = couponOrderDiscountCents(
406	          {
407	            kind: coupon.kind,
408	            value: coupon.value,
409	            serviceKind: coupon.serviceKind,
410	            planSlug: coupon.planSlug,
411	            maxTermMonths: coupon.maxTermMonths,
412	            active: coupon.active,
413	            expiresAt: coupon.expiresAt,
414	            maxRedemptions: coupon.maxRedemptions,
415	            timesRedeemed: coupon.timesRedeemed,
416	            minAmountCents: coupon.minAmountCents,
417	          },
418	          {
419	            serviceKind: "VPS",
420	            planSlug: plan.slug,
421	            planMonthlyCents: plan.priceCents,
422	            termMonths: term.months,
423	            // Coupon discounts the intro-reduced plan portion, so an intro price and a
424	            // coupon cannot together drive the plan charge below zero, and a percentage
425	            // coupon is honestly "% off what you actually pay this term".
426	            planChargeCents: introFirstTermPlanCents,
427	          },
428	          new Date(),
429	        );
430	        if (verdict.ok) {
431	          couponId = coupon.id;
432	          couponDiscountCents = verdict.discountCents;
433	          couponLabel = verdict.label;
434	          couponMaxRedemptions = coupon.maxRedemptions;
435	          couponFirstTimeOnly = coupon.firstTimeOnly;
436	        } else {
437	          couponError = verdict.error;
438	        }
439	      }
440	    }
441	  }
442	
443	  const chargeCents = introFirstTermPlanCents - couponDiscountCents + ipCents + extraDiskCents + backupCents;
444	  return {
445	    plan,
446	    os,
447	    term,
448	    chargeCents,
449	    // Intro pricing (0 / null on plans without one). `introDiscountCents` is the
450	    // first-term saving already baked into `chargeCents`; `introFirstTermPlanCents`
451	    // is the plan-portion cash the first term is sold at; the monthly figures drive
452	    // the honest "$intro first term, then $regular/mo" copy on the pricing cards.
453	    introDiscountCents,
454	    introFirstTermPlanCents,
455	    introMonthlyCents,
456	    introTermMonths,
457	    introRenewalMonthly,
458	    introPercent,
459	    // The annual-discount rate this quote was priced at — snapshot onto the Server at
460	    // sale (Finding 2) so every later proration reads the SAME basis and a round trip
461	    // nets to zero even if the admin retunes `annual_discount_percent` in between.
462	    annualPct,
463	    promo,
464	    promoCreditCents,
465	    regularPlanCents,
466	    extraDiskGB,
467	    extraDiskMonthlyCents,
468	    extraDiskCents,
469	    backupTier,
470	    backupMonthlyCents,
471	    backupCents,
472	    couponId,
473	    couponDiscountCents,
474	    couponLabel,
475	    couponError,
476	    couponMaxRedemptions,
477	    couponFirstTimeOnly,
478	  };
479	}
