481	/**
482	 * Place an order: validate, charge the wallet (unless a free admin grant),
483	 * create the Server + PROVISION job. Returns the new server id. Does NOT
484	 * redirect. Callers must ensure funds exist (or pass free) — this still
485	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
486	 *
487	 * `sold` overrides the recomputed price with the one the order was actually SOLD
488	 * at — the card-paid path passes the figure stamped on the Checkout session
489	 * BEFORE the card was charged, so the confirm redirect settles the price the
490	 * customer consented to instead of re-pricing against whatever promo is running
491	 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
492	 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
493	 * quote, which it computed moments ago in the same request. See OrderPrice.
494	 */
495	/**
496	 * Claim a checkout coupon in ITS OWN atomic transaction, throwing OrderError on
497	 * any failure so nothing partial survives. Kept separate from the order tx so a
498	 * wallet order can surface the failure before any money moves, and a card order
499	 * (already paid) can swallow it without stranding the paid provision.
500	 *
501	 * Guards, all enforced here: first-time-only (no prior paid server), the
502	 * redemption cap (atomic conditional increment), one-per-account and one-per-IP
503	 * (the two @@unique constraints on CouponRedemption).
504	 */
505	async function claimOrderCoupon(opts: {
506	  couponId: string;
507	  maxRedemptions: number | null;
508	  firstTimeOnly: boolean;
509	  userId: string;
510	  ipHash: string | null;
511	  amountCents: number;
512	}): Promise<void> {
513	  await db.$transaction(async (tx) => {
514	    // Self-heal first: a dead hold from THIS customer's own abandoned card checkout must
515	    // not stand between them and this coupon on a fresh (wallet) order — and its global
516	    // slot is handed back here too. Guarded to expired RESERVED rows (lib/coupon-redemption.ts).
517	    await releaseExpiredCouponHoldsFor(tx, opts.couponId, opts.userId, opts.ipHash);
518	    if (opts.firstTimeOnly) {
519	      const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
520	      if (prior > 0) throw new OrderError("This code is for first-time customers only.");
521	    }
522	    // Atomic conditional increment — the only thing between the last free slot and
523	    // an over-redemption when two orders race for it.
524	    const claim = await tx.coupon.updateMany({
525	      where:
526	        opts.maxRedemptions === null
527	          ? { id: opts.couponId, active: true }
528	          : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
529	      data: { timesRedeemed: { increment: 1 } },
530	    });
531	    if (claim.count !== 1) throw new OrderError("That code has just been fully claimed.");
532	    try {
533	      await tx.couponRedemption.create({
534	        data: { couponId: opts.couponId, userId: opts.userId, ipHash: opts.ipHash, amountCents: opts.amountCents, context: "order" },
535	      });
536	    } catch {
537	      // Unique violation on (coupon,user) or (coupon,ipHash): already claimed by
538	      // this person. Throwing rolls back the increment above with it.
539	      throw new OrderError("You’ve already used this code.");
540	    }
541	  });
542	}
