544	/**
545	 * Read-only mirror of `claimOrderCoupon`'s per-person guards, for the CARD path.
546	 *
547	 * The card leg discounts `cardCents` up front and only settles the redemption
548	 * AFTER the card is charged — where a failed claim is deliberately swallowed so a
549	 * paid provision is never stranded. Without this pre-check, a customer who has
550	 * already used a one-per-person code (or isn't first-time) still gets the
551	 * discounted card charge and the swallow hides it. So before we send them to
552	 * checkout we re-run first-time-only, one-per-account, one-per-IP and the cap as
553	 * plain reads; if any fails the caller re-quotes at full price. This is advisory
554	 * (a race could still lose the atomic claim at settle time — that path stays
555	 * swallowed by design), but it closes the everyday bypass.
556	 */
557	export async function orderCouponClaimable(opts: {
558	  couponId: string;
559	  firstTimeOnly: boolean;
560	  maxRedemptions: number | null;
561	  userId: string;
562	  ipHash: string | null;
563	}): Promise<{ ok: true } | { ok: false; error: string }> {
564	  if (opts.firstTimeOnly) {
565	    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
566	    if (prior > 0) return { ok: false, error: "This code is for first-time customers only." };
567	  }
568	  const byUser = await db.couponRedemption.findUnique({
569	    where: { couponId_userId: { couponId: opts.couponId, userId: opts.userId } },
570	  });
571	  if (byUser) return { ok: false, error: "You’ve already used this code." };
572	  if (opts.ipHash) {
573	    const byIp = await db.couponRedemption.findFirst({ where: { couponId: opts.couponId, ipHash: opts.ipHash } });
574	    if (byIp) return { ok: false, error: "This code has already been claimed from your connection." };
575	  }
576	  if (opts.maxRedemptions !== null) {
577	    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
578	    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
579	  }
580	  return { ok: true };
581	}
