583	export async function placeOrder(
584	  user: User,
585	  intent: OrderIntent,
586	  sold?: OrderPrice | null,
587	  opts?: {
588	    ipHash?: string | null;
589	    campaign?: string;
590	    promoReservationToken?: string | null;
591	    couponReservationToken?: string | null;
592	  },
593	): Promise<string> {
594	  const quote = await orderQuote(intent);
595	  const { plan, os, term, promo, promoCreditCents, extraDiskGB, extraDiskMonthlyCents, extraDiskCents, backupTier, backupMonthlyCents, backupCents } = quote;
596	  // Everything below bills off THESE three, never off `quote.chargeCents` /
597	  // `promo` directly: when a sold price is present it is the whole truth about
598	  // what this order costs and what rate it was sold at.
599	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
600	  const promoPercent = sold?.promoPercent ?? promo.discountPercent;
601	  const promoName = sold?.promoName || promo.name;
602	  // Note the intro discount on the billing document (first term only; renews full).
603	  const promoNote = promoPercent > 0 ? ` · ${promoName} ${promoPercent}% off first term` : "";
604	
605	  // Managed first-month-free — how this order settles the credit depends on the path:
606	  //   WALLET path (no `sold`): the credit rides on the fresh quote (promoCreditCents
607	  //     > 0), and we contend for it with an atomic INSERT inside the charge tx below.
608	  //   CARD/Stripe path (`sold` present): the credit was already RESERVED before the
609	  //     card was charged, and its hold token travels in `opts.promoReservationToken`.
610	  //     We CONFIRM that hold (never a fresh contended INSERT) — that is what closes
611	  //     the double-claim race. No token => this order was sold at FULL price, so there
612	  //     is nothing to grant. We deliberately do NOT infer the credit from
613	  //     `sold.promoPercent` (currentPromo always stamps 100, even on a full-price VPS
614	  //     order), which would record a redemption for a purchase that never got one.
615	  const walletPromoApplied = !sold && promoCreditCents > 0;
616	  const cardPromoToken = sold ? opts?.promoReservationToken ?? null : null;
617	  // The checkout coupon settles the same two ways:
618	  //   WALLET path (no `sold`): atomic claim in its OWN tx below (claimOrderCoupon), which
619	  //     throws and surfaces before any money moves if the last slot just went.
620	  //   CARD/Stripe path (`sold`): the coupon was RESERVED before the card was charged and
621	  //     its hold token travels in `opts.couponReservationToken`. We CONFIRM that hold
622	  //     inside the charge tx (never a fresh contended claim — that would double-count the
623	  //     global cap and collide on the per-person unique). No token => full-price order.
624	  const cardCouponToken = sold ? opts?.couponReservationToken ?? null : null;
625	
626	  const cap = await capacityCheck(plan.id);
627	  if (!cap.ok) throw new OrderError(cap.reason);
628	
629	  let nodeId: string | null = null;
630	  if (intent.nodeId) {
631	    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
632	    if (!n) throw new OrderError("Selected location is not available.");
633	    nodeId = n.id;
634	  } else {
635	    const n = await scheduleNode(plan.ramMB);
636	    nodeId = n?.id ?? null;
637	  }
638	
639	  // Reserve the EFFECTIVE size (plan + upsold extra) — the VM really is that big.
