1	// Single fulfilment path for a paid Stripe Checkout session, shared by BOTH the
2	// success-redirect route and the webhook. Plain server module (not "use server").
3	//
4	// WHY THIS EXISTS (2026-07-25)
5	// Fulfilment used to live in `app/api/stripe/confirm/route.ts` and was gated on
6	// whether `creditCheckoutSession()` returned true. That boolean is true only for
7	// the caller that won the race to insert the wallet credit — and the webhook
8	// calls the same function and discards the result. So:
9	//
10	//   * Race: the webhook's insert lands first, the confirm request gets P2002,
11	//     `credited === false`, and the redirect quietly lands on an empty page.
12	//     $249 charged, $249 credited, no server, no error, no notification.
13	//   * Deterministic: the customer closes the tab before `success_url` resolves,
14	//     so the confirm route never runs at all. Same outcome, 100% reproducible.
15	//
16	// Stripe's own guidance is explicit that a browser redirect must not be the
17	// fulfilment trigger. Now BOTH callers run this, and a `FulfilledSession` row —
18	// its own marker, not a side effect of crediting — decides the single winner.
19	
20	import { db } from "./db";
21	import { classifyCheckoutSession, creditCheckoutSession, retrieveCheckoutSession } from "./stripe";
22	import { placeOrder } from "./order";
23	import { placeGameOrder } from "./game-order";
24	import { applyResize } from "./resize";
25	import { applyDiskExpand } from "./disk-expand";
26	import { sendMetaConversion } from "./tracking";
27	import { cookies, headers } from "next/headers";
28	
29	export type FulfilResult = {
30	  /** Where the browser should end up. The webhook ignores this. */
31	  redirect: string;
32	  /** True when THIS call performed the fulfilment work. */
33	  fulfilled: boolean;
34	  kind: "order" | "gameOrder" | "resize" | "diskExpand" | "topup" | "none";
35	  error?: string;
36	};
37	
38	/**
39	 * Claim exclusive responsibility for fulfilling `sessionId`.
40	 * Returns false when another caller already holds the claim — the UNIQUE index,
41	 * not a read-then-write check, is what makes this safe under concurrency.
42	 */
43	async function claim(sessionId: string, kind: string): Promise<boolean> {
44	  try {
45	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionId, kind } });
46	    return true;
47	  } catch (e) {
48	    if ((e as { code?: string })?.code === "P2002") return false; // someone else has it
49	    throw e;
50	  }
51	}
52	
53	async function settle(sessionId: string, status: "DONE" | "FAILED", detail?: string) {
54	  await db.fulfilledSession
55	    .update({ where: { stripeSessionId: sessionId }, data: { status, detail: detail?.slice(0, 500) } })
56	    .catch(() => {});
57	}
58	
59	/**
60	 * Tell the customer their money is safe and someone knows. Called only on a path
61	 * where the card HAS cleared and fulfilment did not happen, so silence is the one
62	 * outcome that is never acceptable.
63	 */
64	async function notifyStalled(userId: string) {
65	  await db.notification
66	    .create({
67	      data: {
68	        userId,
69	        title: "Payment received — we couldn't finish setting up your server",
70	        body: "Your payment is safe and sitting in your wallet. Our team has been alerted; deploy again or contact support and we'll sort it out.",
71	        href: "/dashboard/billing",
72	      },
73	    })
74	    .catch(() => {});
75	}
