77	/**
78	 * Report a completed order as an ad-conversion, exactly once, on the WINNING fulfil
79	 * call (this only runs where `fulfilled === true`, so no double count under the
80	 * redirect/webhook race). Fires the server-side Meta Conversions API event — best
81	 * effort, inert unless the pixel id + CAPI token are set, and it never throws into
82	 * fulfilment — then returns the redirect tagged with the SAME event_id and the real
83	 * charged amount (`session.amount_total`, what Stripe actually took), so the browser
84	 * pixel (`PurchaseTracker`) can fire and Meta dedupes the pair into ONE conversion.
85	 * READ-ONLY on money: it reports the amount, it never changes a charge.
86	 */
87	async function reportPurchase(
88	  redirect: string,
89	  session: Awaited<ReturnType<typeof retrieveCheckoutSession>>,
90	  email?: string,
91	  userId?: string,
92	  /** Product kind for the per-funnel Google Ads conversion ("vps" | "game"). */
93	  prod?: string,
94	): Promise<string> {
95	  const value = typeof session.amount_total === "number" ? session.amount_total / 100 : 0;
96	  if (!(value > 0)) return redirect; // free / zero-charge order — nothing to report
97	  const currency = (session.currency ?? "usd").toUpperCase();
98	  // Best-effort match signals from the request: the Meta _fbc/_fbp cookies + UA/IP.
99	  // Wrapped so the webhook path (no browser request scope) simply sends without them.
100	  let fbc: string | undefined, fbp: string | undefined, userAgent: string | undefined, clientIp: string | undefined;
101	  try {
102	    const [ck, h] = await Promise.all([cookies(), headers()]);
103	    fbc = ck.get("_fbc")?.value || undefined;
104	    fbp = ck.get("_fbp")?.value || undefined;
105	    userAgent = h.get("user-agent") ?? undefined;
106	    clientIp = (h.get("x-forwarded-for")?.split(",")[0] ?? "").trim() || undefined;
107	  } catch {
108	    /* no request scope (webhook) — send without cookie/UA signals */
109	  }
110	  const { eventId } = await sendMetaConversion({
111	    eventName: "Purchase",
112	    email,
113	    value,
114	    currency,
115	    sourceUrl: redirect,
116	    fbc,
117	    fbp,
118	    userAgent,
119	    clientIp,
120	    externalId: userId,
121	  });
122	  const params = new URLSearchParams({ purchase: "1", pv: value.toFixed(2), pc: currency, pe: eventId, ...(prod ? { prod } : {}) });
123	  return `${redirect}${redirect.includes("?") ? "&" : "?"}${params.toString()}`;
124	}
