142	  const session = await retrieveCheckoutSession(sessionId);
143	  const purpose = classifyCheckoutSession(session);
144	
145	  // Nothing was paid (an abandoned session id, or one replayed before capture).
146	  // Never claim fulfilment for money that has not arrived.
147	  if (purpose.kind === "unpaid") {
148	    return { redirect: `${base}/dashboard/billing`, fulfilled: false, kind: "none" };
149	  }
150	
151	  // Crediting is separately idempotent (UNIQUE stripeSessionId on the wallet
152	  // transaction). We deliberately IGNORE its return value now — it reports who
153	  // won the credit race, which is not the same question as "has this been
154	  // fulfilled", and conflating the two was the bug. A THROW, however, is not a
155	  // race: the money has not reached the wallet, so nothing below may spend it.
156	  await creditCheckoutSession(session);
157	
158	  // Purchase metadata is present but cannot be trusted. Retrying will never fix
159	  // it, so claim the session and record the failure exactly like a failed order:
160	  // reconcilable, and the customer is told. What it must NEVER become is a silent
161	  // wallet top-up, which is precisely what the old `null` fall-through produced.
162	  if (purpose.kind === "unreadable") {
163	    if (await claim(sessionId, "unreadable")) {
164	      await settle(sessionId, "FAILED", purpose.detail);
165	      if (purpose.userId) await notifyStalled(purpose.userId);
166	    }
167	    return {
168	      redirect: `${base}/dashboard/billing?paid=1`,
169	      fulfilled: false,
170	      kind: "none",
171	      error: purpose.detail,
172	    };
173	  }
174	
175	  const order = purpose.kind === "order" ? purpose : null;
176	  if (order) {
177	    if (!(await claim(sessionId, "order"))) {
178	      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "order" };
179	    }
180	    try {
181	      const user = await db.user.findUnique({ where: { id: order.userId } });
182	      if (!user) throw new Error("user not found for paid order");
183	      // Settle the price stamped on the session BEFORE the card was charged — never
184	      // a fresh quote taken now. The customer has already paid the card leg of that
185	      // exact total; re-pricing here and taking the difference out of the wallet is
186	      // the H2 incident (see OrderPrice in lib/order.ts). This is the same shape as
187	      // the resize and disk-expand branches below, which have always passed the
188	      // amount through metadata for this reason.
189	      // No request-scoped IP on the fulfil path (this can run in the webhook), so the
190	      // per-IP cap can't be enforced here — the per-account unique still holds, and
191	      // the first-month-free HOLD was already reserved (per-account AND per-IP) before
192	      // the card was charged, so the double-claim race is closed regardless. Fulfilment
193	      // CONFIRMS that hold via `promoReservationToken` rather than contending for a
194	      // fresh claim. `campaign` rides in via metadata so attribution survives the card
195	      // round-trip even in the webhook (no cookies).
196	      const serverId = await placeOrder(user, order.intent, order.sold, {
197	        ipHash: null,
198	        campaign: order.campaign,
199	        promoReservationToken: order.promoReservationToken,
200	        // Same discipline as the promo hold: the coupon was RESERVED (per-person + global
201	        // cap) before the card was charged, and placeOrder CONFIRMS that hold via this
202	        // token rather than contending for a fresh claim — no double-claim, no over-charge.
203	        couponReservationToken: order.couponReservationToken,
204	      });
205	      await settle(sessionId, "DONE", serverId);
206	      const redirect = await reportPurchase(`${base}/dashboard/servers/${serverId}`, session, user.email, user.id, "vps");
207	      return { redirect, fulfilled: true, kind: "order" };
208	    } catch (e) {
209	      // Payment is captured and the funds are in the wallet — record the failure
210	      // so it is reconcilable rather than invisible, and tell the customer.
211	      const msg = String((e as Error)?.message ?? e);
212	      await settle(sessionId, "FAILED", msg);
213	      await notifyStalled(order.userId);
214	      return { redirect: `${base}/dashboard/deploy?paid=1`, fulfilled: false, kind: "order", error: msg };
215	    }
216	  }
217	
218	  // Game-server order — the game analogue of the `order` branch above. Same claim /
219	  // settle / notify discipline; the card leg was credited to the wallet by
220	  // `creditCheckoutSession` above, then `placeGameOrder` debits the SOLD total back
221	  // out — never a fresh quote taken now (the H2 re-pricing incident). Game carries
222	  // no promo/coupon hold, so there is nothing to confirm and no per-IP concern here.
223	  const gameOrder = purpose.kind === "gameOrder" ? purpose : null;
224	  if (gameOrder) {
225	    if (!(await claim(sessionId, "gameOrder"))) {
226	      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "gameOrder" };
227	    }
228	    try {
229	      const user = await db.user.findUnique({ where: { id: gameOrder.userId } });
230	      if (!user) throw new Error("user not found for paid game order");
231	      const serverId = await placeGameOrder(user, gameOrder.intent, gameOrder.sold);
232	      await settle(sessionId, "DONE", serverId);
233	      const redirect = await reportPurchase(`${base}/dashboard/servers/${serverId}`, session, user.email, user.id, "game");
234	      return { redirect, fulfilled: true, kind: "gameOrder" };
235	    } catch (e) {
236	      // Payment is captured and the funds are in the wallet — record the failure so
237	      // it is reconcilable rather than invisible, and tell the customer.
238	      const msg = String((e as Error)?.message ?? e);
239	      await settle(sessionId, "FAILED", msg);
240	      await notifyStalled(gameOrder.userId);
241	      return { redirect: `${base}/dashboard/games?paid=1`, fulfilled: false, kind: "gameOrder", error: msg };
242	    }
243	  }
244	
245	  const resize = purpose.kind === "resize" ? purpose : null;
246	  if (resize) {
247	    const back = `${base}/dashboard/servers/${resize.serverId}`;
248	    if (!(await claim(sessionId, "resize"))) {
249	      return { redirect: back, fulfilled: false, kind: "resize" };
250	    }
251	    try {
252	      await applyResize({
253	        serverId: resize.serverId,
254	        planId: resize.planId,
255	        actorUserId: resize.userId,
256	        chargeCents: resize.chargeCents,
257	      });
258	      await settle(sessionId, "DONE", resize.serverId);
259	      return { redirect: back, fulfilled: true, kind: "resize" };
260	    } catch (e) {
261	      const msg = String((e as Error)?.message ?? e);
262	      await settle(sessionId, "FAILED", msg);
263	      await notifyStalled(resize.userId);
264	      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "resize", error: msg };
265	    }
266	  }
267	
268	  const expand = purpose.kind === "diskExpand" ? purpose : null;
269	  if (expand) {
270	    const back = `${base}/dashboard/servers/${expand.serverId}`;
271	    if (!(await claim(sessionId, "diskExpand"))) {
272	      return { redirect: `${back}?tab=resize`, fulfilled: false, kind: "diskExpand" };
273	    }
274	    try {
275	      await applyDiskExpand({
276	        serverId: expand.serverId,
277	        addGB: expand.addGB,
278	        actorUserId: expand.userId,
279	        chargeCents: expand.chargeCents,
280	      });
281	      await settle(sessionId, "DONE", expand.serverId);
282	      return { redirect: `${back}?tab=resize`, fulfilled: true, kind: "diskExpand" };
283	    } catch (e) {
284	      const msg = String((e as Error)?.message ?? e);
285	      await settle(sessionId, "FAILED", msg);
286	      await notifyStalled(expand.userId);
287	      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "diskExpand", error: msg };
288	    }
289	  }
290	
291	  // Plain wallet top-up: crediting above is the whole job. Reached ONLY when the
292	  // session genuinely carried no purchase metadata — never because we failed to
293	  // read it (that throws) and never because we failed to parse it ("unreadable").
294	  return { redirect: `${base}/dashboard/billing?paid=1`, fulfilled: true, kind: "topup" };
295	}
