1	import { NextRequest, NextResponse } from "next/server";
2	import { stripe, stripeConfigured } from "@/lib/stripe";
3	import { fulfilCheckoutSession } from "@/lib/fulfil-checkout";
4	import { releaseReservation } from "@/lib/promo-redemption";
5	import { releaseOrderCouponReservation } from "@/lib/coupon-redemption";
6	import type Stripe from "stripe";
7	
8	export async function POST(req: NextRequest) {
9	  if (!stripeConfigured() || !process.env.STRIPE_WEBHOOK_SECRET) {
10	    return NextResponse.json({ error: "not configured" }, { status: 400 });
11	  }
12	  const sig = req.headers.get("stripe-signature");
13	  if (!sig) return NextResponse.json({ error: "missing signature" }, { status: 400 });
14	  const raw = await req.text();
15	
16	  let event;
17	  try {
18	    event = stripe().webhooks.constructEvent(raw, sig, process.env.STRIPE_WEBHOOK_SECRET);
19	  } catch {
20	    return NextResponse.json({ error: "invalid signature" }, { status: 400 });
21	  }
22	
23	  if (event.type === "checkout.session.completed") {
24	    const session = event.data.object as { id: string };
25	    // FULFIL, don't just credit. This used to call `creditCheckoutSession` and
26	    // throw the result away, which meant the webhook credited the wallet and then
27	    // — by winning the race — caused the success-redirect to see `credited: false`
28	    // and skip provisioning entirely. The webhook is the reliable signal (the
29	    // redirect may never happen at all), so it must be able to fulfil on its own.
30	    // `fulfilCheckoutSession` is idempotent via UNIQUE(FulfilledSession), so the
31	    // two callers racing is safe: exactly one does the work.
32	    //
33	    // Errors are swallowed deliberately — returning non-2xx makes Stripe retry the
34	    // event, and the failure is already recorded on the FulfilledSession row and
35	    // surfaced to the customer.
36	    try {
37	      await fulfilCheckoutSession(session.id);
38	    } catch (e) {
39	      console.error("[stripe-webhook] fulfil failed", session.id, e);
40	    }
41	  }
42	
43	  // A checkout the customer never completed: Stripe expires it (we cap the payable
44	  // window at ORDER_CHECKOUT_EXPIRES_MS). RELEASE any first-month-free hold it carried
45	  // so the customer's one-time offer is returned promptly rather than waiting for the
46	  // worker sweep. Guarded to RESERVED, so a completed+confirmed grant is never revoked.
47	  // (If this event type isn't enabled in the Stripe dashboard, the worker sweep is the
48	  // backstop — the hold's reservedUntil has passed by the time the session expires.)
49	  if (event.type === "checkout.session.expired") {
50	    const session = event.data.object as Stripe.Checkout.Session;
51	    const token = session.metadata?.nxeonPromoReservation;
52	    if (token) {
53	      try {
54	        await releaseReservation(token);
55	      } catch (e) {
56	        console.error("[stripe-webhook] release reservation failed", token, e);
57	      }
58	    }
59	    // Same for a checkout-coupon hold — return its per-person slot AND its global-cap
60	    // slot (timesRedeemed decrement inside releaseOrderCouponReservation). Guarded to
61	    // RESERVED, so a completed+confirmed CONSUMED redemption is never revoked.
62	    const couponToken = session.metadata?.nxeonCouponReservation;
63	    if (couponToken) {
64	      try {
65	        await releaseOrderCouponReservation(couponToken);
66	      } catch (e) {
67	        console.error("[stripe-webhook] release coupon reservation failed", couponToken, e);
68	      }
69	    }
70	  }
71	
72	  return NextResponse.json({ received: true });
73	}
