167	/**
168	 * Feature + capacity gate shared by both game order entry points: the game-servers
169	 * feature can be switched off platform-wide (flag), and game servers are Server rows
170	 * too so they count toward the per-user cap. Returns a customer-facing error to
171	 * surface, or null to proceed. The email-verification gate is applied INLINE at each
172	 * entry point so the "consult the gate before taking money" invariant is visible at
173	 * the call site (see test/auth-lockouts.test.ts B4).
174	 *
175	 * The MONEY-CRITICAL guards (plan validity, image, capacity, balance, atomic debit)
176	 * live in `placeGameOrder` (lib/game-order.ts), so the Stripe fulfilment path is
177	 * safe WITHOUT this gate — this only fronts the interactive order actions, exactly
178	 * as `serverLimitError` fronts `payAndDeploy` for VPS.
179	 */
180	async function gameOrderGate(user: User): Promise<string | null> {
181	  if (!(await getSettingBool("feature_game_servers", true))) {
182	    return "Game servers aren't available right now.";
183	  }
184	  const cap = await getSettingInt("max_servers_per_user", 10);
185	  if (cap > 0) {
186	    const owned = await db.server.count({ where: { userId: user.id, status: { notIn: ["DELETING"] } } });
187	    if (owned >= cap) {
188	      return `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}.`;
189	    }
190	  }
191	  return null;
192	}
