196	  let config: Record<string, unknown> | null = null;
197	  const rawConfig = formData.get("config");
198	  if (typeof rawConfig === "string" && rawConfig.trim() !== "") {
199	    try {
200	      const parsed = JSON.parse(rawConfig);
201	      if (parsed && typeof parsed === "object") config = parsed as Record<string, unknown>;
202	    } catch {
203	      // A malformed config blob is dropped, not trusted — `gameOrderQuote` then
204	      // fills defaults. It can never widen the charge (game is a flat term price).
205	      config = null;
206	    }
207	  }
208	  return {
209	    gamePlanId: String(formData.get("gamePlanId") ?? ""),
210	    termMonths: Number(formData.get("termMonths") ?? 1),
211	    serverName: String(formData.get("serverName") ?? "").trim() || undefined,
212	    hostname: String(formData.get("hostname") ?? "").trim() || undefined,
213	    variant: String(formData.get("variant") ?? "").trim() || undefined,
214	    config,
215	  };
