218	/**
219	 * Wizard checkout for a game server — the game analogue of `payAndDeploy`, built on
220	 * the SAME audited machinery: it reuses `walletSplit` for the wallet/card split,
221	 * `placeGameOrder` (lib/game-order.ts) as the ONE debit path, and — when a card leg
222	 * is needed — `createGameOrderCheckout` + the shared Stripe fulfilment bus
223	 * (lib/fulfil-checkout.ts) that also settles VPS orders. No new charge path.
224	 *
225	 * MONEY: game bills FULL from month 1 — no first-month-free, no coupon, no VAT
226	 * change. The charge is the DB-fed term price (`gameOrderQuote.chargeCents`), the
227	 * SOLD price is stamped on the Checkout session BEFORE the card is charged, and
228	 * fulfilment settles that exact figure (never re-quoted after the card cleared).
229	 * displayed (wizard) === charged (here) === renewed (renewalCharge).
230	 */
231	export async function payAndDeployGame(
232	  _prev: unknown,
233	  formData: FormData,
234	): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
235	  const user = await requireUser();
236	  // Spend path: never move a customer's money while an admin is impersonating them.
237	  await assertNotImpersonating();
238	  // Purchase gate: an unverified address means we cannot reach the person we are
239	  // about to charge (see lib/email-verification.ts). Consulted before any money moves.
240	  const unverified = await emailVerificationError(user);
241	  if (unverified) return { error: unverified };
242	  const gateErr = await gameOrderGate(user);
243	  if (gateErr) return { error: gateErr };
244	
245	  const intent = gameIntentFromFormData(formData);
246	
247	  let quote;
248	  try {
249	    quote = await gameOrderQuote(intent);
250	  } catch (e) {
251	    if (e instanceof GameOrderError) return { error: e.message };
252	    throw e;
253	  }
254	
255	  // The full, DB-fed term price. No promo/coupon/VAT adjustment for game.
256	  const chargeCents = quote.chargeCents;
257	
258	  // Wallet-aware split — the wizard computes the identical split (lib/wallet-split.ts)
259	  // from the same inputs, so what the customer sees === what we charge. `useWallet`
260	  // defaults ON (only "0" turns it off).
261	  const useWallet = formData.get("useWallet") !== "0";
262	  const { cardCents } = walletSplit({ dueCents: chargeCents, balanceCents: user.balanceCents, useWallet });
263	
264	  // Card portion is $0 (the wallet covers the whole charge) → provision straight
265	  // away through the audited debit. `placeGameOrder` debits the FULL chargeCents
266	  // from the wallet; its balance check holds because cardCents <= 0 means the
267	  // balance already covers the charge.
268	  if (cardCents <= 0) {
269	    let serverId: string;
270	    try {
271	      serverId = await placeGameOrder(user, intent, null);
272	    } catch (e) {
273	      if (e instanceof GameOrderError) return { error: e.message };
274	      throw e;
275	    }
276	    redirect(`/dashboard/servers/${serverId}`);
277	  }
278	
279	  // Card leg > 0 → charge ONLY the remainder on the card. On payment success the
280	  // confirm/webhook route credits this card amount to the wallet and THEN
281	  // placeGameOrder debits the full chargeCents, so the wallet naturally absorbs the
282	  // applied balance and the card the rest — the wallet is never touched before the
283	  // card clears. The SOLD price is handed over EXPLICITLY (stamped before any
284	  // charge), so a rate change between now and fulfilment can't re-price it.
285	  const sold: GameOrderPrice = { chargeCents };
286	  let checkout: EmbeddedCheckout | null;
287	  try {
288	    checkout = await createGameOrderCheckout(user, cardCents, intent, sold);
289	  } catch (e) {
290	    if (e instanceof GameOrderError) return { error: e.message };
291	    throw e;
292	  }
293	  if (!checkout) {
294	    return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
295	  }
296	  return { checkout };
297	}
