98	/**
99	 * Order a shared-hosting account for a domain on a plan. Same purchase discipline
100	 * as every other paid path: no spending while impersonating, verified email,
101	 * wallet charge in the same tx that creates the record. The account starts
102	 * PENDING; the worker provisioner brings it up (inert until shared hosting is
103	 * enabled — see worker/hosting.ts).
104	 */
105	export async function orderHostingAccount(
106	  planId: string,
107	  domain: string,
108	  termMonthsRaw?: number,
109	  subdomainLabelRaw?: string,
110	  extraDiskGBRaw?: number,
111	): Promise<HostingResult> {
112	  const user = await requireUser();
113	  await assertNotImpersonating();
114	  const unverified = await emailVerificationError(user);
115	  if (unverified) return { error: unverified };
116	
117	  // OPTIONAL domain. An empty domain means "start me on a free temporary
118	  // `<username>.nxeon.cloud` subdomain, I'll connect a real domain later" — the
119	  // customer is never forced to own a domain to sign up. A REAL domain keeps every
120	  // cross-tenant guard it always had; the temp subdomain is derived from the
121	  // account's own per-node-unique username (below) so it can't collide with
122	  // anything a customer typed, and its uniqueness is still enforced by the SAME
123	  // atomic UNIQUE(hostname) claim inside the charge tx.
124	  const wantTemp = !String(domain ?? "").trim();
125	  let name = "";
126	  if (!wantTemp) {
127	    name = normalizeHostingDomain(domain);
128	    if (!name) return { error: "Enter a domain." };
129	    if (!isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
130	  }
131	
132	  const plan = await db.hostingPlan.findUnique({ where: { id: planId } });
133	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
134	
135	  if (!wantTemp) {
136	    // One account per domain across ALL customers — same cross-tenant guard as
137	    // email subscriptions (a shared vhost keys on server_name).
138	    const dupe = await db.hostingAccount.findFirst({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } });
139	    if (dupe) {
140	      return {
141	        error:
142	          dupe.userId === user.id
143	            ? "You already have a hosting account for this domain."
144	            : "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across.",
145	      };
146	    }
147	    // Also reject if this hostname is already someone's subdomain or addon domain
148	    // (audit HIGH-2: the primary-order guard used to ignore those two tables).
149	    if (await isHostnameClaimed(name)) {
150	      return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
151	    }
152	  }
153	
154	  const node = await scheduleHostingNode();
155	  if (!node) return { error: "No shared-hosting capacity is available right now — please try again shortly." };
156	
157	  // Managed first-month-free. `promoCharge` is $0 (a single-month hosting term is
158	  // free); `fullCharge` is the plan price. The credit is granted ONLY if the atomic
159	  // claim inside the charge tx succeeds — otherwise (already redeemed by this
160	  // account/IP, or the promo is off) the account is created at FULL price. We
161	  // pre-check eligibility only to pick the balance gate: a first-time customer with
162	  // a $0 balance can still sign up free, a repeat one is gated against full price.
163	  // First-month-free is scoped to Shared Web Hosting (this flow) — the one
164	  // product the promo applies to. See firstMonthFreeAppliesTo.
165	  const promoEnabled = firstMonthFreeAppliesTo("HOSTING") && (await firstMonthFreeEnabled());
166	  const campaign = promoCampaignFromCookie(await cookies());
167	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
168	  // Billing term (Monthly / Annual). The annual rate is the admin setting, resolved
169	  // ONCE here, frozen onto the account, charged up front and read back at renewal —
170	  // so displayed === charged === renewed. A malformed term falls back to monthly.
171	  const term = normalizeProductTerm(termMonthsRaw);
172	  const annualPct = await annualDiscountPct();
173	  const limits = planLimits(plan);
174	  // Optional extra storage bought at deploy (on-step, in-range). Priced per-GB/month
175	  // at the SAME rate VPS extra disk uses and multiplied over the whole term. It is an
176	  // ADD-ON: never discounted by the term promo (the free month applies to the plan
177	  // only), so `extraTermCents` is added AFTER the credit — displayed === charged.
178	  const extraGB = normalizeExtraDiskAddGB(extraDiskGBRaw);
179	  if (effectiveDiskGB(limits.diskGB, extraGB) > EXTRA_DISK_MAX_TOTAL_GB) {
180	    return { error: `Storage tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB — choose a smaller add-on.` };
181	  }
182	  const perGbCents = await extraDiskPerGbCents();
183	  const extraTermCents = extraDiskCentsAt(extraGB, perGbCents) * term;
184	  // PLAN term price (the promo-creditable part) vs the true TOTAL the customer pays.
185	  const planTermCents = termPriceCents(plan.priceCents, term, annualPct);
186	  const fullCharge = planTermCents + extraTermCents;
187	  // First-month-free must credit EXACTLY ONE MONTH of the PLAN — never zero a whole
188	  // annual term, and never touch the storage add-on. `firstMonthCreditCents(planTermCents,
189	  // term)` returns the full plan charge for a 1-month term (genuinely free first month)
190	  // and one month's share for the annual term; the storage add-on is always charged.
191	  const promoCharge = Math.max(0, planTermCents - firstMonthCreditCents(planTermCents, term)) + extraTermCents;
192	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
193	  const anticipated = eligible ? promoCharge : fullCharge;
194	  if (user.balanceCents < anticipated) return { error: "Insufficient balance. Top up your wallet first." };
195	  const username = await pickUsername(node.id, user.email.split("@")[0] ?? "acct");
196	  // Free temporary subdomain: derived from the just-allocated (per-node-unique)
197	  // username, validated the same way a real domain is and de-duplicated by the same
198	  // atomic hostname claim inside the tx. The advisory pre-check here is friendly UX
199	  // only — a collision across nodes is caught authoritatively by UNIQUE(hostname).
200	  if (wantTemp) {
201	    // A customer-CHOSEN free subdomain (`<label>.<base>`) if they picked one in the
202	    // wizard, else the auto-derived `<username>.<base>`. Either way it lives under our
203	    // `*.<HOSTING_SUBDOMAIN_BASE>` wildcard, so it resolves + gets HTTPS automatically
204	    // (no A record for the customer to set). The chosen label is validated here and
205	    // de-duplicated by the SAME atomic UNIQUE(hostname) claim inside the charge tx —
206	    // the wizard's live availability check (checkHostingSubdomain) is advisory UX only.
207	    const label = String(subdomainLabelRaw ?? "").trim().toLowerCase();
208	    if (label) {
209	      if (!isValidSubdomainLabel(label)) {
210	        return { error: "Choose a subdomain of 1–32 letters, digits or hyphens (start/end with a letter or digit)." };
211	      }
212	      name = freeSubdomainFor(label);
213	      if (!isValidHostingDomain(name)) return { error: "That subdomain isn’t a valid hostname — try a different one." };
214	      if (await isHostnameClaimed(name)) {
215	        return { error: `${name} is already taken — please choose another subdomain.` };
216	      }
217	    } else {
218	      name = tempSubdomainFor(username);
219	      if (!isValidHostingDomain(name)) return { error: "Couldn’t allocate a temporary subdomain — please try again." };
220	      if (await isHostnameClaimed(name)) return { error: "Couldn’t allocate a temporary subdomain — please try again." };
221	    }
222	  }
223	
224	  let accountId = "";
225	  try {
226	    await db.$transaction(async (tx) => {
227	      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
228	      let debitCents = fullCharge;
229	      let promoClaimId: string | null = null;
230	      // MONEY BUG FIX (2026-08-12): gate the claim on `eligible`, NOT `promoEnabled`.
231	      // claimFirstMonthFree INSERTs a redemption row and catches the P2002 unique
232	      // violation ("already redeemed") to return {claimed:false}. But Postgres POISONS
233	      // the whole transaction the instant any statement fails — a caught error does
234	      // NOT un-abort it — so the very next statement (debitWallet's updateMany) then
235	      // dies with 25P02 ("current transaction is aborted"). Result: EVERY repeat
236	      // customer who already used the free month could no longer place a hosting order
237	      // (the order failed, wallet never charged). `eligible` is the same authoritative
238	      // per-user/per-IP precheck (firstMonthFreeEligible) resolved above, so an
239	      // ineligible/repeat customer now skips the doomed INSERT entirely and is charged
240	      // full price cleanly. The atomic anti-double-grant guarantee is preserved: two
241	      // concurrent ELIGIBLE orders still both run the claim, one wins, the loser's tx
242	      // poisons on P2002 and fails safe (no charge, no second free month) — retry pays
243	      // full. So exactly one free month is ever granted.
244	      if (eligible) {
245	        const claim = await claimFirstMonthFree(tx, {
246	          userId: user.id,
247	          ipHash,
248	          serviceType: "HOSTING",
249	          campaign,
250	          chargedCents: promoCharge,
251	        });
252	        if (claim.claimed) {
253	          debitCents = promoCharge;
254	          promoClaimId = claim.id;
255	        }
256	      }
257	      const note = (debitCents < fullCharge ? " — First month free" : "") + (extraGB > 0 ? ` + ${extraGB} GB storage` : "");
258	      // Term shown on the ledger line: an annual account reads "Annual ($X.XX/mo)"
259	      // so the customer sees the yearly commitment AND its real per-month rate. Uses the
260	      // PLAN per-month rate (the add-on has its own $/GB/mo shown in the storage note).
261	      const effMonthly = term > 1 ? Math.round(planTermCents / term) : 0;
262	      const termLabel = term > 1 ? `${vpsTerm(term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(term).label;
263	      await debitWallet(tx, user.id, debitCents);
264	      await tx.walletTransaction.create({
265	        data: { userId: user.id, amountCents: -debitCents, description: `Web Hosting: ${plan.name} for ${name} — ${termLabel}${note}` },
266	      });
267	      const acct = await tx.hostingAccount.create({
268	        // Cast: the symlinked prod Prisma client's types predate `termMonths` /
269	        // `annualDiscountPct` on HostingAccount until it is regenerated at deploy
270	        // (identical at runtime then — see lib/order.ts's Server create).
271	        data: {
272	          userId: user.id,
273	          hostingNodeId: node.id,
274	          planId: plan.id,
275	          username,
276	          primaryDomain: name,
277	          status: "PENDING",
278	          // Quota already folds in the purchased extra disk, so the node's setquota
279	          // (applyIsolation → taskApplyPlanLimits) provisions the right size with no
280	          // add-on awareness of its own.
281	          diskQuotaMB: effectiveDiskGB(limits.diskGB, extraGB) * 1024,
282	          extraDiskGB: extraGB,
283	          maxSites: limits.maxSites,
284	          maxDatabases: limits.maxDatabases,
285	          // The term this account was SOLD on, and the annual rate frozen at sale, so
286	          // the renewal sweep bills the SAME price it was ordered at (worker/product-renewals.ts).
287	          termMonths: term,
288	          annualDiscountPct: annualPct,
289	          expiresAt: addMonths(new Date(), term),
290	        } as Prisma.HostingAccountUncheckedCreateInput,
291	      });
292	      accountId = acct.id;
293	      // Atomic hostname claim in the SAME tx as the account row. A colliding
294	      // primaryDomain (another order, or someone's subdomain/addon of the same
295	      // name racing us past the advisory isHostnameClaimed check) fails here on
296	      // UNIQUE(hostname) → the whole tx (incl. the wallet debit) rolls back.
297	      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(name), accountId: acct.id, kind: "PRIMARY" } });
298	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, acct.id, debitCents);
299	    });
300	  } catch (e) {
301	    if (isUniqueViolation(e)) {
302	      return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
303	    }
304	    // The generic message below is intentionally opaque to the customer, but the
305	    // REAL error must be diagnosable server-side (e.g. prod schema drift: a
306	    // HostingAccount.termMonths/annualDiscountPct column or the HostingHostnameClaim
307	    // table missing because a `prisma db push` didn't apply → the INSERT throws
308	    // here). Log it before swallowing. No money-logic change — the tx already rolled
309	    // back, so the wallet was NOT charged.
310	    console.error("[hosting.order] failed", {
311	      userId: user.id,
312	      planId,
313	      domain: name,
314	      code: (e as { code?: string })?.code,
315	      err: e instanceof Error ? e.message : e,
316	    });
317	    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
318	  }
319	
320	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.order", detail: `${plan.name} · ${name}` } }).catch(() => {});
321	  revalidatePath("/dashboard/hosting");
322	  return { ok: true, accountId };
323	}
