325	// ---------- Checkout wizard (payment-method-captured order) ------------------
326	//
327	// THE MONEY FIX. `orderHostingAccount` above debits the WALLET only. First-month-
328	// free (hosting-only) makes a monthly plan $0 for month 1, so the wallet path used
329	// to provision with NOTHING on file — and month-2's renewal had nothing to charge.
330	// `placeHostingOrder` is the wizard's single entry point and closes that gap: it
331	// REFUSES to provision unless the account has a way to bill the renewal (a saved
332	// card OR a wallet balance that already covers one renewal), it is idempotent
333	// against double-submit, and it then delegates the ACTUAL charge to the audited
334	// `orderHostingAccount` above — one debit path, never a second one.
335	//
336	// displayed === charged === renewed: this action computes NO price of its own for
337	// the debit. The wallet debit + the first-month-free reserve→confirm→release
338	// atomicity all live inside `orderHostingAccount`; `renewalCents` here is only the
339	// gate threshold and is the SAME `termPriceCents(plan.priceCents, term, annualPct)`
340	// the renewal sweep charges (worker/product-renewals.ts hostingRenewalPrice).
341	
342	export type HostingOrderInput = {
343	  planId: string;
344	  /** Empty/omitted => a free `<label|username>.<base>` subdomain (see subdomainLabel). */
345	  domain?: string;
346	  /** Customer-chosen free-subdomain label (used only when `domain` is empty). */
347	  subdomainLabel?: string;
348	  /** Optional extra storage (GB) bought at deploy, on top of the plan allowance. */
349	  extraDiskGB?: number;
350	  termMonths?: number;
351	  /** Optional catalog app to auto-install after the account provisions. */
352	  appSlug?: string;
353	  /** Client-generated token that makes a resubmit a no-op (double-submit guard). */
354	  idempotencyKey: string;
355	};
356	
357	export type HostingOrderResult =
358	  | { ok: true; accountId: string }
359	  | { error: string }
360	  /** No renewal-capable payment method yet — the wizard must capture a card first. */
361	  | { needCard: true; renewalCents: number };
362	
363	/**
364	 * The full-price single renewal of a plan/term — the gate threshold, identical to
365	 * what the renewal sweep bills so "wallet covers a renewal" means exactly that.
366	 */
367	async function hostingRenewalCents(plan: { priceCents: number }, term: number, extraGB = 0): Promise<number> {
368	  const annualPct = await annualDiscountPct();
369	  const perGbCents = await extraDiskPerGbCents();
370	  return termPriceCents(plan.priceCents, term, annualPct) + extraDiskCentsAt(extraGB, perGbCents) * term;
371	}
