373	/** Place a hosting order from the checkout wizard. See the block comment above. */
374	export async function placeHostingOrder(input: HostingOrderInput): Promise<HostingOrderResult> {
375	  const user = await requireUser();
376	  await assertNotImpersonating();
377	  const unverified = await emailVerificationError(user);
378	  if (unverified) return { error: unverified };
379	
380	  const key = String(input.idempotencyKey ?? "").trim();
381	  if (!/^[A-Za-z0-9_-]{8,64}$/.test(key)) return { error: "Couldn’t place the order — please reload and try again." };
382	
383	  const term = normalizeProductTerm(input.termMonths);
384	  const plan = await db.hostingPlan.findUnique({ where: { id: input.planId } });
385	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
386	
387	  // RENEWAL-METHOD GATE — the core fix. Never provision a paid product with no way
388	  // to bill the renewal. A saved card (charged off-session by the renewal sweep) OR
389	  // a wallet already holding one renewal's worth qualifies; otherwise the wizard
390	  // sends the customer to Stripe to capture a card (which also handles the $0-today
391	  // case, where no card would otherwise be collected).
392	  const extraGB = normalizeExtraDiskAddGB(input.extraDiskGB);
393	  const renewalCents = await hostingRenewalCents(plan, term, extraGB);
394	  if (!hasChargeableCard(user) && user.balanceCents < renewalCents) {
395	    return { needCard: true, renewalCents };
396	  }
397	
398	  // IDEMPOTENCY — reuse the audited FulfilledSession one-winner primitive (its
399	  // UNIQUE(stripeSessionId) is what the card path leans on) rather than inventing a
400	  // token table. A rapid resubmit or a network retry with the same key can't create
401	  // a second account or take a second debit.
402	  const sessionKey = `hostorder:${key}`;
403	  try {
404	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
405	  } catch (e) {
406	    if (isUniqueViolation(e)) {
407	      const prior = await db.fulfilledSession.findUnique({ where: { stripeSessionId: sessionKey } });
408	      // A completed prior attempt: replay its result (no second charge).
409	      if (prior?.status === "DONE" && prior.detail) return { ok: true, accountId: prior.detail };
410	      // A failed prior attempt: clear it so an explicit retry can proceed.
411	      if (prior?.status === "FAILED") {
412	        await db.fulfilledSession.delete({ where: { stripeSessionId: sessionKey } }).catch(() => {});
413	      } else {
414	        // Still in flight (CLAIMED): a concurrent submit is placing it right now.
415	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
416	      }
417	      // Retry after clearing a FAILED marker: re-claim, or bail if we lost the race.
418	      try {
419	        await db.fulfilledSession.create({ data: { stripeSessionId: sessionKey, kind: "hostorder" } });
420	      } catch {
421	        return { error: "That order is already being placed — check your hosting accounts in a moment." };
422	      }
423	    } else {
424	      throw e;
425	    }
426	  }
427	
428	  // Delegate the ACTUAL charge to the audited wallet path. An empty domain routes to
429	  // the free temporary subdomain. All money movement, the first-month-free atomic
430	  // claim and the hostname claim happen inside orderHostingAccount's transaction.
431	  const res = await orderHostingAccount(input.planId, input.domain ?? "", term, input.subdomainLabel, extraGB);
432	  if (res.error || !res.accountId) {
433	    await db.fulfilledSession
434	      .update({ where: { stripeSessionId: sessionKey }, data: { status: "FAILED", detail: (res.error ?? "order failed").slice(0, 500) } })
435	      .catch(() => {});
436	    return { error: res.error ?? "Couldn’t place the order. Your wallet was not charged — try again." };
437	  }
438	  await db.fulfilledSession
439	    .update({ where: { stripeSessionId: sessionKey }, data: { status: "DONE", detail: res.accountId } })
440	    .catch(() => {});
441	
442	  // Server-side Meta CAPI `Subscribe` — the free-month hosting signup is a browser-
443	  // ONLY conversion otherwise (HostingDeployWizard fires nxTrack('hosting') client-
444	  // side), so an ad blocker / privacy browser silently drops it and the campaign
445	  // never learns the signup happened. Firing it here too — with the SAME event_id
446	  // the browser pixel uses (idempotencyKey) — means Meta dedupes the two into ONE
447	  // conversion when the pixel DOES load, and still counts it when the pixel is
448	  // blocked. Value = the go-forward renewal (what optimisation should chase), NOT $0.
449	  // Best-effort: sendMetaConversion never throws, and this runs after the order is
450	  // already committed, so tracking can never affect the charge.
451	  try {
452	    const [h, ck] = await Promise.all([headers(), cookies()]);
453	    await sendMetaConversion({
454	      eventName: "Subscribe",
455	      eventId: key,
456	      email: user.email,
457	      externalId: user.id,
458	      value: renewalCents / 100,
459	      currency: "USD",
460	      clientIp: clientIp(h),
461	      userAgent: h.get("user-agent") ?? undefined,
462	      // The Meta click/browser cookies are the strongest match signals for an
463	      // ad-driven signup (an ad click sets _fbc). Passing them lifts Event Match
464	      // Quality well above the email/IP-only baseline. Absent for organic visits.
465	      fbc: ck.get("_fbc")?.value || undefined,
466	      fbp: ck.get("_fbp")?.value || undefined,
467	      sourceUrl: process.env.APP_URL ? `${process.env.APP_URL}/dashboard/deploy` : undefined,
468	    });
469	  } catch {
470	    /* tracking is best-effort — the order is already placed and charged */
471	  }
472	
473	  // Optional one-click app install: queue it now so the worker installs it the
474	  // moment the account finishes provisioning. Best-effort — a bad slug never voids
475	  // the (already-charged) order; the customer can install from the panel later.
476	  const slug = String(input.appSlug ?? "").trim();
477	  if (slug) {
478	    try {
479	      await queueHostingAppInstall(res.accountId, slug, plan.maxDatabases, user.email);
480	    } catch {
481	      /* non-fatal: the account is created and charged; the app can be installed later */
482	    }
483	  }
484	
485	  revalidatePath("/dashboard/hosting");
486	  return { ok: true, accountId: res.accountId };
487	}
