491	 * Advisory UX for the deploy wizard — the authoritative de-dup is the atomic
492	 * UNIQUE(hostname) claim inside orderHostingAccount's charge tx, so a check that
493	 * says "available" can still lose a race and fail the order cleanly (no charge).
494	 */
495	export async function checkHostingSubdomain(
496	  labelRaw: string,
497	): Promise<{ available: boolean; fqdn: string; reason?: string }> {
498	  await requireUser();
499	  const label = String(labelRaw ?? "").trim().toLowerCase();
500	  const fqdn = freeSubdomainFor(label);
501	  if (!label) return { available: false, fqdn, reason: "Enter a subdomain." };
502	  if (!isValidSubdomainLabel(label)) {
503	    return { available: false, fqdn, reason: "Use 1–32 letters, digits or hyphens (start/end with a letter or digit)." };
504	  }
505	  if (!isValidHostingDomain(fqdn)) {
