514	/**
515	 * Queue an APP_INSTALL for a freshly-ordered (PENDING) account. Mirrors installApp
516	 * but without the ACTIVE gate — the task waits in the queue and the worker runs it
517	 * after provisioning. Generates DB credentials up front for apps that need one.
518	 */
519	async function queueHostingAppInstall(accountId: string, slug: string, maxDatabases: number, email: string): Promise<void> {
520	  // WordPress is NOT an APP_RECIPES download — it installs via its own fully-
521	  // automated WORDPRESS_INSTALL task (WP-CLI). Route the wizard's one-click
522	  // WordPress here so it queues the right task with the same credential payload
523	  // installWordPress builds (mirrors that path). Any other slug must be a known
524	  // recipe app; an unknown slug is dropped (best-effort — never voids the order).
525	  if (slug === "wordpress") {
526	    if (maxDatabases < 1) return; // WordPress needs a database — no budget, skip rather than fail
527	    const acct = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { username: true } });
528	    if (!acct) return;
529	    const dbName = `${acct.username}_wp`.slice(0, 64);
530	    const dbUser = dbName.slice(0, 32);
531	    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
532	    const adminPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 18);
533	    await db.hostingTask.create({
534	      data: {
535	        accountId,
536	        kind: "WORDPRESS_INSTALL",
537	        payload: JSON.stringify({ dbName, dbUser, dbPassEnc: encryptSecret(dbPass), adminUser: "admin", adminPassEnc: encryptSecret(adminPass), adminEmail: email }),
538	      },
539	    });
540	    return;
541	  }
542	  const app = hostingAppCatalog().find((x) => x.slug === slug);
543	  if (!app) return;
544	  let payload: Record<string, unknown> = { slug };
545	  if (app.needsDb) {
546	    if (maxDatabases < 1) return; // the plan has no DB budget — skip rather than fail
547	    const acct = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { username: true } });
548	    if (!acct) return;
549	    const dbName = `${acct.username}_${slug}`.slice(0, 64);
550	    const dbUser = dbName.slice(0, 32);
551	    const dbPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
552	    payload = { slug, dbName, dbUser, dbPassEnc: encryptSecret(dbPass) };
553	  }
554	  await db.hostingTask.create({ data: { accountId, kind: "APP_INSTALL", payload: JSON.stringify(payload) } });
555	}
