712	/** Create a scoped database for an account (within the plan's maxDatabases). */
713	export async function createHostingDatabase(accountId: string, label: string): Promise<{ error?: string; ok?: boolean; password?: string }> {
714	  const user = await requireUser();
715	  await assertNotImpersonating();
716	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, username: true, maxDatabases: true } });
717	  if (!a) return { error: "Account not found." };
718	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
719	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
720	  // A short, safe suffix keyed off the account username: <user>_<slug>.
721	  const slug = String(label ?? "").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db";
722	  const name = `${a.username}_${slug}`.slice(0, 64);
723	  const dbUser = name.slice(0, 32);
724	  if (!/^[a-z0-9_]{1,64}$/.test(name)) return { error: "Invalid database name." };
725	  const password = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
726	  // Count + create in ONE serializable transaction, so concurrent creates can't
727	  // both read a stale count and blow past the plan cap (audit 2026-08-01 TOCTOU).
728	  try {
729	    await db.$transaction(async (tx) => {
730	      const n = await tx.hostingDatabase.count({ where: { accountId: a.id, status: { in: ["PENDING", "ACTIVE"] } } });
731	      if (n >= a.maxDatabases) throw new Error("CAP");
732	      await tx.hostingDatabase.create({ data: { accountId: a.id, name, dbUser, passwordEnc: encryptSecret(password), status: "PENDING" } });
733	    }, { isolationLevel: "Serializable" });
734	  } catch (e) {
735	    if (e instanceof Error && e.message === "CAP") return { error: `Your plan allows ${a.maxDatabases} database${a.maxDatabases === 1 ? "" : "s"}.` };
736	    // Serialization conflict (P2034) or the unique(accountId,name) collision.
737	    return { error: "A database with that name already exists, or the request raced — try again." };
738	  }
739	  revalidatePath("/dashboard/hosting");
740	  // Shown ONCE — the encrypted copy is cleared by the provisioner after it applies it.
741	  return { ok: true, password };
742	}
