753	/**
754	 * Reveal a hosting database's stored password (owner or admin, never while
755	 * impersonating — same discipline as revealHostingSftpPassword, audit LOW-1). The
756	 * password is kept encrypted on the row now (the provisioner no longer wipes it),
757	 * so a customer can look it up any time. If it was never stored (a legacy row, or a
758	 * WordPress/app DB from before this shipped), they can Reset to set a fresh one.
759	 */
760	export async function revealHostingDbPassword(dbId: string): Promise<{ password?: string; error?: string }> {
761	  const user = await requireUser();
762	  await assertNotImpersonating();
763	  const d = await db.hostingDatabase.findUnique({
764	    where: { id: dbId },
765	    select: { passwordEnc: true, account: { select: { userId: true } } },
766	  });
767	  if (!d) return { error: "Not found." };
768	  if (d.account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
769	  if (!d.passwordEnc) return { error: "No stored password — reset it to set a new one." };
770	  const pw = decryptSecret(d.passwordEnc);
771	  if (!pw) return { error: "Couldn’t read the stored password — reset it to set a new one." };
772	  return { password: pw };
