775	/**
776	 * Reset a hosting database's password (owner or admin, never while impersonating).
777	 * Generates a new alphanumeric password, queues a RESET_DB_PASSWORD task that runs
778	 * `ALTER USER … IDENTIFIED BY …` on the node, and stores the new (encrypted) value
779	 * so it can be viewed later. Returned ONCE to the caller for display. No money logic.
780	 */
781	export async function resetHostingDbPassword(dbId: string): Promise<{ password?: string; error?: string }> {
782	  const user = await requireUser();
783	  await assertNotImpersonating();
784	  const d = await db.hostingDatabase.findUnique({
785	    where: { id: dbId },
786	    select: { id: true, dbUser: true, accountId: true, account: { select: { userId: true } } },
787	  });
788	  if (!d) return { error: "Not found." };
789	  if (d.account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
790	  const newPass = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
791	  await db.hostingTask.create({
792	    data: {
793	      accountId: d.accountId,
794	      // New enum value applied by `prisma db push` at promote (additive/safe; the
795	      // symlinked prod Prisma client's types predate it until regenerated — cast,
796	      // identical at runtime, same pattern as HostingAccount.termMonths above).
797	      kind: "RESET_DB_PASSWORD" as Prisma.HostingTaskUncheckedCreateInput["kind"],
798	      payload: JSON.stringify({ dbUser: d.dbUser, passEnc: encryptSecret(newPass) }),
