815	export async function installDbTool(accountId: string): Promise<{ ok?: boolean; error?: string; url?: string }> {
816	  const user = await requireUser();
817	  await assertNotImpersonating();
818	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, dbToolPath: true } });
819	  if (!a) return { error: "Account not found." };
820	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
821	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
822	  if (a.dbToolPath) return { ok: true, url: a.dbToolPath };
823	  // Don't queue a second install while one is already in flight.
824	  const inFlight = await db.hostingTask.findFirst({ where: { accountId, kind: "INSTALL_DBTOOL", status: { in: ["PENDING", "RUNNING"] } } });
825	  if (inFlight) return { ok: true };
826	  const token = randomBytes(16).toString("hex").slice(0, 32); // 32 lowercase hex chars
827	  if (!isValidDbToolToken(token)) return { error: "Couldn’t start the install — try again." };
828	  const path = `/nxtools-${token}/adminer.php`;
829	  await db.hostingTask.create({ data: { accountId, kind: "INSTALL_DBTOOL", payload: JSON.stringify({ token, path }) } });
830	  revalidatePath(`/dashboard/hosting/${accountId}`);
831	  return { ok: true };
832	}
