854	  const rows = await db.hostingTask.findMany({ where: { accountId }, orderBy: { createdAt: "desc" }, take: 8 });
855	  // A DONE result may carry a one-time secret (WordPress admin pw). Return it once,
856	  // then clear it so it isn't shown again on the next poll.
857	  const out = rows.map((t) => ({ id: t.id, kind: t.kind, status: t.status, result: t.result, error: t.error, createdAt: t.createdAt.toISOString() }));
858	  // A DONE result may carry a one-time note; clear it after one read so it isn't
859	  // re-shown on every poll — EXCEPT an app-install's admin login, which the customer
860	  // needs long-term (WordPress passwords aren't recoverable). Those persist and are
861	  // surfaced in the Overview's App Credentials panel (getHostingAppCredentials).
862	  const toClear = rows.filter(
863	    (t) => t.status === "DONE" && t.result && t.kind !== "WORDPRESS_INSTALL" && t.kind !== "APP_INSTALL",
864	  );
865	  if (toClear.length) await db.hostingTask.updateMany({ where: { id: { in: toClear.map((t) => t.id) } }, data: { result: null } });
