52	/**
53	 * The one-month first-month-free credit, computed EXACTLY like the server's
54	 * `firstMonthCreditCents` (kept inline so this client file never imports the
55	 * db-backed promo module). A 1-month term is wholly free; a longer term credits a
56	 * single month. The server recomputes the real debit with the same formula, so
57	 * displayed === charged.
58	 */
59	function firstMonthCredit(fullCents: number, months: number): number {
60	  if (months <= 1) return fullCents;
61	  return Math.min(fullCents, Math.round(fullCents / months));
62	}
